/**
 * Compares the parser output against the output of the original Python library.
 *
 * The expected values are generated by `scripts/generate-upstream-fixtures.py`.
 */
import path from 'path';
import { readFileSync } from 'fs';
import {
  ParserManager,
  Eagerness,
  ComfyUIParser,
  PromptInfo,
  getFullPrompt,
  getFullNegativePrompt,
} from '../../src';

const RESOURCES = path.join(__dirname, '../resources');
const fixture = JSON.parse(readFileSync(path.join(RESOURCES, 'upstream-expected.json'), 'utf-8'));

const FIELD_NAMES: Record<string, string> = {
  rawParameters: 'raw_parameters',
  samplerId: 'sampler_id',
  negativePrompts: 'negative_prompts',
  modelId: 'model_id',
  promptId: 'prompt_id',
};

/**
 * Convert a PromptInfo into the shape produced by the Python library's `dataclasses.asdict()`
 */
function toUpstreamShape(promptInfo: PromptInfo): any {
  // rename fields to snake_case and fill in the optional fields python sets to None
  const rename = (value: Record<string, any>, optional: string[]) => {
    const renamed = Object.fromEntries(Object.entries(value).map(([key, v]) => [FIELD_NAMES[key] ?? key, v]));
    for (const key of optional) {
      renamed[key] ??= null;
    }
    return renamed;
  };

  const prompt = (p: any) => rename(p, ['prompt_id']);

  return JSON.parse(
    JSON.stringify({
      full_prompt: getFullPrompt(promptInfo),
      full_negative_prompt: getFullNegativePrompt(promptInfo),
      generator: promptInfo.generator,
      samplers: promptInfo.samplers.map(sampler => ({
        ...rename(sampler, ['sampler_id']),
        model: sampler.model ? rename(sampler.model, ['name', 'hash', 'model_id']) : null,
        prompts: sampler.prompts.map(prompt),
        negative_prompts: sampler.negativePrompts.map(prompt),
      })),
      metadata: promptInfo.metadata,
      raw_parameters: promptInfo.rawParameters,
    })
  );
}

describe('Parity with the upstream Python library', () => {
  const parserManager = new ParserManager();

  describe.each(Object.entries(fixture.images as Record<string, Record<string, any>>))('%s', (file, results) => {
    it.each(Object.entries(results))('eagerness %s', async (level, expected) => {
      const eagerness = Eagerness[level as keyof typeof Eagerness];
      const parse = parserManager.parse(path.join(RESOURCES, file), eagerness);

      if (expected && 'error' in expected) {
        await expect(parse).rejects.toThrow();
        return;
      }

      const result = await parse;
      if (expected === null) {
        expect(result).toBeNull();
      } else if (level === 'EAGER') {
        expect(toUpstreamShape(result!)).toEqual(expected);
      } else {
        expect(result?.generator).toBe(expected.generator);
      }
    });
  });

  describe.each(Object.entries(fixture.parsers as Record<string, any>))('%s', (_name, testCase) => {
    it('produces the same output', async () => {
      expect(testCase.parser).toBe('ComfyUIParser');
      const result = await new ComfyUIParser().parse(testCase.parameters);
      expect(toUpstreamShape(result)).toEqual(testCase.expected);
    });
  });
});
